public static void solve() {
    java.util.Scanner in = new java.util.Scanner(System.in);
    int H = in.nextInt();
    int height = 0;
    int day = 0;

    while (height <= H) {
        int growth = (int) Math.pow(2, day);
        height += growth;
        day++;
    }

    System.out.print(day);
}
